<script setup lang="ts">
import {computed} from 'vue'
import type {Task} from '@/domain/types'
import {toolMap,taskStatusLabels} from '@/domain/tools'
import {text} from './model'
const props=defineProps<{modelValue:boolean;task:Task|null}>()
defineEmits<{'update:modelValue':[value:boolean]}>()
const files=computed(()=>props.task?.draft?.files ?? [])
</script>
<template><el-dialog :model-value="modelValue" title="任务信息" width="min(900px, calc(100vw - 24px))" @update:model-value="$emit('update:modelValue',$event)" destroy-on-close><template v-if="task"><el-descriptions :column="2" border><el-descriptions-item label="任务名称">{{task.name}}</el-descriptions-item><el-descriptions-item label="分析工具">{{task.tool ? toolMap[task.tool]?.name : '工具类型待确认'}}</el-descriptions-item><el-descriptions-item label="分析状态">{{taskStatusLabels[task.status]}}</el-descriptions-item><el-descriptions-item label="提交时间">{{task.createdAt || '未返回'}}</el-descriptions-item><el-descriptions-item label="处理范围">{{task.total}} 份 · 完成 {{task.completed}} · 失败 {{task.failed}}</el-descriptions-item><el-descriptions-item label="当前阶段">{{task.stage || '未返回'}}</el-descriptions-item></el-descriptions><el-alert v-if="task.error" :title="task.error" type="error" :closable="false" show-icon class="info-block"/><el-collapse class="info-block"><el-collapse-item :title="`分析资料（${files.length} 份）`" name="files"><el-table :data="files" max-height="280"><el-table-column prop="name" label="资料名称"/><el-table-column prop="path" label="所在目录" show-overflow-tooltip/><el-table-column label="附件" width="90"><template #default="{row}">{{task.draft?.attachments[row.id]?.length ?? 0}} 份</template></el-table-column></el-table><p v-if="!files.length" class="muted">服务未返回执行资料快照。</p></el-collapse-item><el-collapse-item title="执行提示词" name="prompts"><template v-if="task.draft && Object.keys(task.draft.prompts).length"><section v-for="(prompt,key) in task.draft.prompts" :key="key"><h4>{{prompt.name || key}}</h4><pre class="readable-text">{{prompt.content}}</pre></section></template><p v-else class="muted">本任务未返回提示词快照。</p></el-collapse-item><el-collapse-item title="执行参数" name="config"><pre class="readable-text">{{task.draft ? text(task.draft.config) : '服务未返回完整执行配置，暂不能再次分析。'}}</pre></el-collapse-item></el-collapse><p class="muted">任务编号：{{task.id}}</p></template><template #footer><el-button @click="$emit('update:modelValue',false)">关闭</el-button></template></el-dialog></template>
<style scoped>.info-block{margin-top:16px}.readable-text{font:inherit;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fa;padding:16px;max-height:400px;overflow:auto}.muted{color:#596b80;font-size:14px}h4{margin:12px 0}</style>
